<?php
function prod_signs($arr) {
    // Helper function to check if a number is prime
    function is_prime($n) {
        if ($n < 2) {
            return false;
        }
        for ($i = 2; $i <= sqrt($n); $i++) {
            if ($n % $i == 0) {
                return false;
            }
        }
        return true;
    }

    // Filter out unique prime numbers from the array
    $primes = array_filter(array_unique($arr), function($i) {
        return is_prime(abs($i));
    });

    // If there are no prime numbers, return null
    if (empty($primes)) {
        return null;
    }

    // Calculate the sum based on the count of each prime number in the original array
    $sum = 0;
    foreach ($primes as $prime) {
        // If the count of the prime number in the original array is even, add it
        // Otherwise, subtract it
        if (array_count_values($arr)[$prime] % 2 == 0) {
            $sum += $prime;
        } else {
            $sum -= $prime;
        }
    }

    return $sum;
}

