program BinaryStringQueries;

uses
  SysUtils;

type
  TQuery = array[0..1] of Integer;
  TResult = array[0..1] of Integer;

function BinaryToDecimal(binaryStr: string): Integer;
var
  i: Integer;
  value: Integer;
begin
  value := 0;
  for i := 1 to Length(binaryStr) do
  begin
    value := value * 2 + (Ord(binaryStr[i]) - Ord('0'));
  end;
  Result := value;
end;

function FindShortestSubstring(s: string; first, second: Integer): TResult;
var
  left, right, i, j, n: Integer;
  currentValue: Integer;
begin
  n := Length(s);
  for i := 0 to n - 1 do
  begin
    currentValue := 0;
    for j := i to n - 1 do
    begin
      currentValue := currentValue * 2 + (Ord(s[j + 1]) - Ord('0'));
      if (currentValue Xor first) = second then
      begin
        Result[0] := i;
        Result[1] := j;
        Exit;
      end;
    end;
  end;
  Result[0] := -1;
  Result[1] := -1;
end;

function Solve(s: string; queries: array of TQuery): array of TResult;
var
  i: Integer;
  result: array of TResult;
  query, resultItem: TResult;
begin
  SetLength(result, Length(queries));
  for i := 0 to High(queries) do
  begin
    query := queries[i];
    resultItem := FindShortestSubstring(s, query[0], query[1]);
    result[i] := resultItem;
  end;
  Result := result;
end;

var
  s: string;
  queries: array of TQuery;
  result: array of TResult;
  i: Integer;
begin
  s := '101101';
  SetLength(queries, 2);
  queries[0][0] := 0;
  queries[0][1] := 5;
  queries[1][0] := 1;
  queries[1][1] := 2;

  result := Solve(s, queries);

  for i := 0 to High(result) do
  begin
    WriteLn('[' + IntToStr(result[i][0]) + ',' + IntToStr(result[i][1]) + ']');
  end;
end.
```

