#include <iostream>
#include <unordered_map>
#include <vector>

using namespace std;

int subarraySum(vector<int>& nums, int k) {
    unordered_map<int, int> preSumCount;
    int preSum = 0, result = 0;

    preSumCount[0] = 1; // Initialize the count of the prefix sum 0

    for (int i = 0; i < nums.size(); i++) {
        preSum += nums[i];

        // Check if there's a previous subarray summing up to 'preSum - k'
